export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    // Every listing is walked to its last page: a single page would silently
    // leave the oldest rows (listed last, newest first) out of the index.
    let projectCursor: string | null = null;
    do {
      const projects = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor: projectCursor,
      });

      for (const project of projects.items) {
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      projectCursor = projects.nextCursor;
    } while (projectCursor !== null);

    // Only live issues are indexed. Their comments are walked in one thread
    // query per issue, which returns every row (replies included); archived
    // comments are skipped, while live replies under a deleted parent are kept.
    let issueCursor: string | null = null;
    do {
      const issues = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: issueCursor,
        includeArchived: false,
      });

      for (const issue of issues.items) {
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;

          const thread = await commentRepo.listThread(orgId, issue.id);
          const comments = thread
            .flatMap((node) => [node.comment, ...node.replies])
            .filter(isLive);

          for (const comment of comments) {
            await indexComment(orgId, comment);
            result.processed += 1;
          }
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      issueCursor = issues.nextCursor;
    } while (issueCursor !== null);
  });
}

